const q=new URLSearchParams(location.search),modes={baseline:'Baseline',impeccable:'Impeccable',taste:'Taste Skill',awesome:'Awesome / Editorial'};
let mode=Object.hasOwn(modes,q.get('mode'))?q.get('mode'):'impeccable';
const embedded=q.has('embedded'),frame=q.has('frame');
const sources={impeccable:'https://github.com/pbakaus/impeccable',taste:'https://github.com/Leonxlnx/taste-skill',awesome:'https://github.com/bergside/awesome-design-skills/tree/main/skills/editorial'};
const notes={impeccable:['Clarify the hierarchy','A clear primary action, readable content, grouped controls and deliberate spacing.','Preserve a chosen identity','Keep the forest-green palette and workshop content while improving composition and contrast.'],taste:['Give the subject the stage','Large photographic fields, a subject-specific concept and varied section layouts replace a generic card-grid hero.','Show its opinionated limits','Flat colour, no gradients, no glows, no glass, no eyebrow labels or decorative numbering.'],awesome:['Choose a concrete recipe','This example uses the Editorial recipe: serif display type, restrained colour and publication-like content structure.','Use one style at a time','The collection contains different recipes. Editorial is one selection, not the appearance of the entire pack.']};
const image=(id,alt)=>`<img src="https://images.unsplash.com/${id}?auto=format&fit=crop&w=1000&q=80" alt="${alt}" loading="lazy">`;
const photos=[['photo-1493106641515-6b5631de4bb9','Reference photograph of pottery and clay'],['photo-1455390582262-044cdead277a','Reference photograph of a notebook and writing tools'],['photo-1452587925148-ce544e77e70d','Reference photograph of a camera']];
const workshops=[['Clay, slowly','Shape a small object by hand.','Saturday · 10:00–12:00','£35',photos[0]],['Ideas on paper','Turn a thought into a printed piece.','Saturday · 13:00–15:00','£25',photos[1]],['Look a little closer','Find a new frame in familiar places.','Sunday · 10:00–12:00','£30',photos[2]]];
function specimen(){document.body.className='specimen '+mode;document.querySelector('#root').innerHTML=`<header class="site-header"><a class="wordmark" href="#top">Fieldwork<span>Creative weekends</span></a><nav aria-label="Workshop navigation"><a href="#workshops">Workshops</a><a href="#about">Our approach</a></nav><button class="reserve" data-jump>Find a workshop</button></header><main id="top"><section class="hero"><div class="hero-copy">${mode==='baseline'?'<span class="eyebrow">A NEW WAY TO SPEND YOUR WEEKEND</span>':''}<h1>Make time.<br/>Make something.</h1><p>Small creative workshops for curious people.<br/>Clay, paper and photography. No experience needed.</p><button class="reserve" data-jump>Find a workshop</button><span class="hero-note">London · Small groups · Materials included</span></div><div class="hero-picture">${image(...photos[0])}<span>Space to try. Room to learn.</span></div></section><section id="workshops" class="workshops"><header><h2>A weekend, well spent.</h2><p>Choose your starting point.</p></header><div class="workshop-list">${workshops.map(([t,p,time,price,img],i)=>`<article>${image(...img)}<div><h3>${t}</h3><p>${p}</p><span class="schedule">${time}</span><button data-book="${i}">Choose workshop <b>${price}</b></button></div></article>`).join('')}</div></section><section id="about" class="about"><h2>Less watching.<br/>More making.</h2><div><p>Take a seat at the table. Learn a technique, try an idea, and leave with something you made yourself.</p><p>Everything here is sample content for comparing design guidance. These workshops are fictional. Reference photographs show the subject, not an actual Fieldwork event.</p></div></section><section class="booking" aria-live="polite"><h2 id="choice-title">Your next small adventure.</h2><p id="choice-copy">Choose a workshop above to see its details here.</p><button id="clear-choice" hidden>Clear selection</button></section></main><footer class="site-footer"><strong>Fieldwork</strong><span>Fictional workshop concept · Reference photos from Unsplash</span><a href="https://unsplash.com" target="_blank" rel="noopener">Image source ↗</a></footer>`;
document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>document.querySelector('#workshops').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));
document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>{const w=workshops[+b.dataset.book];document.querySelector('#choice-title').textContent=w[0];document.querySelector('#choice-copy').textContent=w[2]+' · '+w[3]+' · Materials included. Demo selection only; no booking or payment.';document.querySelector('#clear-choice').hidden=false;document.querySelector('.booking').scrollIntoView({behavior:'smooth'});});
document.querySelector('#clear-choice').onclick=()=>{document.querySelector('#choice-title').textContent='Your next small adventure.';document.querySelector('#choice-copy').textContent='Choose a workshop above to see its details here.';document.querySelector('#clear-choice').hidden=true;};
}
if(frame){specimen();}else{
document.body.className='lab'+(embedded?' embedded':'');
document.querySelector('#root').innerHTML=`<header class="lab-header"><a href="index.html#explore">← UI Atlas</a><span>DESIGN SKILLS / GUIDANCE COMPARISON</span><a id="source-link" target="_blank" rel="noopener">Read the skill ↗</a></header><section class="lab-intro"><h1>Same brief.<br/>Different judgement.</h1><p>Fictional brief: a London creative-workshop page. Same name, copy, sessions, prices and image set across all treatments. Compare the hierarchy, composition and visual language.</p></section><div class="lab-toolbar"><div role="group" aria-label="Skill treatment">${Object.entries(modes).filter(([id])=>id!=='baseline').map(([id,n])=>`<button data-mode="${id}">${n}</button>`).join('')}</div><label><input id="compare" type="checkbox" ${embedded||matchMedia('(max-width:700px)').matches?'':'checked'}> Show baseline beside it</label></div><section class="comparison" id="comparison"><article class="baseline-panel"><h2>Baseline <span>Conventional starting point</span></h2><iframe title="Baseline workshop page" src="skills.html?frame=1&mode=baseline"></iframe></article><article><h2 id="treatment-title"></h2><iframe id="treatment" title="Skill guidance treatment"></iframe></article></section><section class="explanation" id="explanation"></section><p class="method">These are original demonstrations of selected guidance read from the skill files, not automated benchmark results or full upstream workflow runs. They show representative choices; a skill can produce many different designs. No skills were installed globally. <a href="skill-lab/NOTES.txt" target="_blank">Method & source notes ↗</a></p>`;
const compare=()=>document.querySelector('#comparison').classList.toggle('single',!document.querySelector('#compare').checked);document.querySelector('#compare').onchange=compare;compare();
function select(next){mode=next;document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===mode));document.querySelector('#treatment-title').textContent=modes[mode];document.querySelector('#treatment').src='skills.html?frame=1&mode='+mode;document.querySelector('#source-link').href=sources[mode];const n=notes[mode];document.querySelector('#explanation').innerHTML=`<article><h3>${n[0]}</h3><p>${n[1]}</p></article><article><h3>${n[2]}</h3><p>${n[3]}</p></article>`;history.replaceState(null,'','?mode='+mode+(embedded?'&embedded=1':''));}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>select(b.dataset.mode));select(mode);
}
